window.docContents[31].resolve({"/Logic/#Logical-Foundations--Logic-in-Lean--The-Logic-of-Lean":{"contents":"\n\nLean's logical core is a \"metalanguage for mathematics\" in\nthe same sense as familiar foundations for paper-and-pencil math, like\nZermelo–Fraenkel Set Theory (ZFC).Mostly, the differences are not too important,\nbut a few points are useful to understand.\n\n\n\n\n\n\n\n","context":"Logical Foundations\u0009Logic in Lean","header":"8.8. The Logic of Lean","id":"/Logic/#Logical-Foundations--Logic-in-Lean--The-Logic-of-Lean"}});